import assert from 'node:assert/strict';
import {catalogue} from './lib/students-catalogue.mjs';
const w=catalogue(),api=w.MT_LEARNING_ENGINE,bank=w.MT_PRACTICE,chapters=w.MT_STUDY.chapters,plain=v=>JSON.parse(JSON.stringify(v));
let memory=null,writes=0,tick=1800000000000;const options={bank,chapters,read:()=>memory,write:(_,v)=>{writes++;memory=plain(v);return true;},now:()=>tick++,random:()=>.25};
let e=api.create({...options,legacyCompleted:['disp-1','removed','disp-1']});assert.deepEqual(plain(e.completed),['disp-1']);assert.equal(e.summary().length,16);assert.equal(e.summary().reduce((n,c)=>n+c.total,0),292);
const q=bank.find(q=>q.id==='practice-c01-q01');e.open(q.id);e.setAnswer(q.id,'−2');assert.equal(e.resume(),q.id);assert.equal(api.parseAnswer('−2'),-2);assert.equal(api.parseAnswer('2,25'),2.25);assert.equal(api.parseAnswer('1e-10'),1e-10);
for(const raw of ['', '0x10','1,000,000','NaN','Infinity','2 metres','1e999'])assert.equal(api.parseAnswer(raw),null,raw);
e.attempt(q.id,String(q.expected+100));assert.ok(!e.completed.includes(q.id));assert.equal(e.draft(q.id).attempts,1);e.attempt(q.id,String(q.expected));e.attempt(q.id,String(q.expected));assert.equal(e.completed.filter(id=>id===q.id).length,1);assert.notEqual(e.resume(),q.id);
e=api.create(options);assert.equal(e.draft(q.id).attempts,3);assert.equal(e.draft(q.id).raw,String(q.expected));assert.equal(e.summary().find(c=>c.number===1).completed,1);
assert.equal(api.grade({expected:0,tolerance:0,relativeTolerance:0},'0').correct,true);assert.equal(api.grade({expected:2,tolerance:0,relativeTolerance:0},'2.0001').correct,false);assert.equal(api.grade({expected:1e-23},'0').correct,false);assert.ok(!api.feedback({expected:1e-23,unit:'J',hint:'Check your method'},'0').message.includes('sign'));
assert.match(api.feedback({expected:2,unit:'m'},'-2').message,/sign/);assert.match(api.feedback({expected:Math.PI,unit:'rad'},'180').message,/degrees/);assert.match(api.feedback({expected:180,unit:'°'},String(Math.PI)).message,/radians/);assert.match(api.feedback({expected:30,unit:'%'},'.3').message,/percentage/);assert.match(api.feedback({expected:2,unit:'m³'},'2000').message,/factor of 1,000/);assert.match(api.feedback({expected:2,unit:'m³'},'2000').message,/cube/);
assert.equal(e.pool([1],'Advanced').length,4);assert.equal(e.pool([]).length,0);assert.throws(()=>e.startTest({chapters:[],count:1}),/chapter/);assert.throws(()=>e.startTest({chapters:[1],count:51}),/between/);assert.throws(()=>e.startTest({chapters:[1],count:1,level:'nonsense'}),/difficulty/);
const completed=e.completed.length,t=e.startTest({chapters:[1,2],level:'Advanced',count:6});assert.equal(t.items.length,6);assert.equal(new Set(t.items.map(q=>q.id)).size,6);assert.ok(t.items.every(q=>[1,2].includes(q.chapter)&&q.level==='Advanced'));assert.throws(()=>e.startTest({chapters:[1],count:1}),/Resume/);assert.equal(e.activeTest.id,t.id);
e.answerTest(t.items[0].id,String(t.items[0].expected));e.answerTest(t.items[1].id,'invalid');e.moveTest(2);e=api.create(options);assert.equal(e.activeTest.index,2);assert.equal(e.activeTest.answers[t.items[0].id],String(t.items[0].expected));assert.equal(e.completed.length,completed,'No grading before submission');assert.throws(()=>e.answerTest('not-in-test','1'),/not in/);
const r=e.submitTest();assert.equal(r.score,1);assert.equal(r.grades.filter(g=>g.unanswered).length,4);assert.equal(e.activeTest,null);assert.equal(e.history.length,1);assert.ok(e.completed.includes(t.items[0].id));assert.throws(()=>e.submitTest(),/No self-test/);
const changed=bank.map(q=>({...q,expected:q.expected+999}));e=api.create({...options,bank:changed});assert.equal(e.history[0].score,1,'Historical grading uses frozen questions');assert.equal(e.history[0].items[0].expected,t.items[0].expected);
for(let i=0;i<12;i++){e.startTest({chapters:[1],count:1});e.submitTest();}assert.equal(e.history.length,10);e.startTest({chapters:[1],count:1});e.discardTest();assert.equal(e.activeTest,null);e.reset();assert.equal(e.completed.length,0);assert.equal(e.history.length,0);assert.equal(e.draft(q.id).raw,'');assert.equal(e.resume(),q.id);
memory={version:999,completed:[q.id]};const before=writes;e=api.create(options);e.setAnswer(q.id,'1');assert.equal(writes,before);assert.equal(memory.version,999);assert.equal(e.storageState,'incompatible');
memory={version:1,completed:['missing',q.id],practice:{[q.id]:{raw:1,attempts:-6}},lastQuestion:'missing',activeTest:{id:'bad'},history:[{id:'bad'}]};e=api.create(options);assert.deepEqual(plain(e.completed),[q.id]);assert.equal(e.draft(q.id).raw,'');assert.equal(e.draft(q.id).attempts,0);assert.equal(e.activeTest,null);assert.equal(e.history.length,0);
e=api.create({...options,read:()=>{throw Error('blocked');},write:()=>{throw Error('blocked');}});e.attempt(q.id,String(q.expected));assert.ok(e.completed.includes(q.id));assert.equal(e.storageState,'unavailable');
const links=w.MT_LEARNING_LINKS.create({formulas:w.MT_FORMULAS,calculators:w.MT_CALCULATORS,study:w.MT_STUDY}),moduleIds=new Set(['beam','transient','ideal-cycle','pump-suction','refrigeration-energy','lift-cross-curves','rlc','engine','mollier','heat','current','stability','trim','finance','cargo']);let linked=0;
for(const q of bank){const rows=links.resources(q);assert.ok(rows.some(r=>r.kind!=='chapter'),q.id+' has a specific resource');for(const r of rows){const u=new URL(r.href,'https://example.test/students/');if(r.kind==='model'){assert.ok(moduleIds.has(u.hash.slice(1)),r.href);assert.equal(u.searchParams.get('exercise'),q.id);}else{const [route,query]=u.hash.slice(1).split('?'),params=new URLSearchParams(query);assert.equal(params.get('from'),q.id);if(r.kind==='formula'){const f=w.MT_FORMULAS.find(f=>f.id===route.slice(8));assert.ok(f,r.href);if(params.has('variant')){const v=w.MT_STUDY.sourceEquationRegister.find(v=>v.id===params.get('variant'));assert.equal(v.formulaId,f.id);assert.notEqual(v.analyticalReview?.decision,'OPEN_MODEL_OR_SOURCE_LIMIT');}}if(r.kind==='calculator')assert.ok(w.MT_CALCULATORS.some(c=>c.id===route.slice(11)));}linked++;}}
console.log(JSON.stringify({status:'PASS',exercises:bank.length,resourceLinks:linked,scope:'Migration, corruption and unavailable storage; numeric parsing and targeted hints; progress/resume; filtered unique self-tests, persistence, deferred grading, snapshot history and reset; all resource targets.'}));
